(function ($) {
    $.fn.extend({
        leanModal: function (options) {
            var defaults = {
                top: 100,
                overlay: 0.5,
                closeButton: null
            };
            var overlay = $("<div id='lean_overlay'></div>");
            $("body").append(overlay);
            options = $.extend(defaults, options);
            return this.each(function () {
                var o = options;
                $(this).click(function (e) {
                    var modal_id = $(this).attr("href");

                    if (modal_id === '#modal' && $(modal_id).length === 0) {
                        var modalHtml = `<div id="modal" class="popupContainer" style="display:none"><header class="popupHeader"><span class="header_title">Login</span><span class="modal_close"><i class="icon-cancel"></i></span></header><section class="popupBody"><div class="social_login box-social"><div class="notification"></div><div><a href="/auth/redirect/google" class="social_box google"><span class="icon"><i class="i-googlePlus"></i></span><span class="icon_title">LOG IN WITH GOOGLE</span></a><a href="javascript:void(0)" id="login_form" class="social_box"><span class="icon"><i class="i-mail"></i></span><span class="icon_title">LOG IN WITH EMAIL</span></a></div><div class="centeredText">Don't have an account?<br><a href="javascript:void(0)" id="register_form" class="font-weight">Sign up with your email address.</a></div></div><div class="user_login edit-form"><form><label>Email</label><input type="email"><div class="alert alert-email"></div><label>Password</label><input type="password"><div class="alert alert-password"></div><div class="checkbox"><input id="remember" type="checkbox" style="margin:0 5px 0 0;"><label for="remember" style="margin:0;">Remember Me</label><label style="margin:0 0 0 auto"><a href="javascript:void(0)" id="forgot_password" class="forgot_password">Forgot Password?</a></label></div><div class="action_btns"><div class="one_half"><a href="javascript:void(0)" class="button btn-modal back_btn"><i class="icon-left-big"></i> Back</a></div><div class="one_half last"><a href="javascript:void(0)" class="button btn-modal" onclick="loginAjax()">Login</a></div></div></form></div><div class="user_register edit-form"><form><div class="box-social"><a href="/auth/redirect/google" class="social_box google"><span class="icon"><i class="i-googlePlus"></i></span><span class="icon_title">SIGN UP WITH GOOGLE</span></a></div><div class="oauth-divider"><span>or</span></div><label>Email</label><input type="email"><div class="alert alert-email"></div><label>Username</label><input type="text"><div class="alert alert-name"></div><label>Password</label><input type="password"><div class="alert alert-password"></div><label>Confirm Password</label><input type="password" name="confirm-password"><div class="alert alert-confirm-password"></div><div class="action_btns"><div class="one_half"><a href="javascript:void(0)" class="button btn-modal back_btn"><i class="icon-left-big"></i> Back</a></div><div class="one_half last"><a href="javascript:void(0)" class="button btn-modal" onclick="registerAjax()">Sign Up</a></div></div></form></div><div class="user_forgot_password edit-form"><form><div class="pb-2"><p style="padding-bottom:10px">Enter your email address that you used to register. We'll send you an email with a link to reset your password.</p><p><i>If you don’t see the email, check other places it might be, like your junk, spam, social, or other folders.</i></p></div><input type="email" placeholder="Email"><div class="alert alert-email"></div><div class="action_btns"><div class="one_half"><a href="javascript:void(0)" class="button btn-modal back_btn_from_forgot_password"><i class="icon-left-big"></i> Back</a></div><div class="one_half last"><a href="javascript:void(0)" class="button btn-modal" onclick="codePasswordResetAjax()">Send</a></div></div></form></div><div class="form_alert"><form><div class="alert"></div></form></div></section></div>`;
                        $("body").append(modalHtml);
                    }

                    var close_menu_mobile = $(this).data("close-menu-mobile");
                    $("#lean_overlay").off('click').click(function () {
                        close_modal(modal_id)
                    });
                    $(document).off('click', o.closeButton).on('click', o.closeButton, function () {
                        close_modal(modal_id)
                    });
                    var modal_height = $(modal_id).outerHeight();
                    var modal_width = $(modal_id).outerWidth();
                    $("#lean_overlay").css({
                        "display": "block",
                        opacity: 0
                    });
                    $("#lean_overlay").fadeTo(200, o.overlay);
                    if (window.screen.width < 1024 && close_menu_mobile == 1) {
                        $(".sidebar-wrapper").removeClass("show");
                        $("html,body").removeClass("navigation").removeClass("ovh")
                    }
                    $('.alert-error').html('');
                    $(modal_id).css({
                        "display": "block",
                        "position": "fixed",
                        "opacity": 0,
                        "z-index": 11000,
                        "left": 50 + "%",
                        "margin-left": -(modal_width / 2) + "px",
                        "top": o.top + "px"
                    });
                    $(modal_id).fadeTo(200, 1);
                    e.preventDefault()
                })
            });

            function close_modal(modal_id) {
                $("#lean_overlay").fadeOut(200);
                $(modal_id).css({
                    "display": "none"
                });
                if (f_reload == true) {
                    location.reload();
                }
            }
        }
    })

    $(".login").leanModal({
        top: 100,
        overlay: 0.6,
        closeButton: ".modal_close"
    });

    key_captcha = '6LdH6VckAAAAAGk5UPKJdES9lQZPwJSIltqozw5y';

    $(document).on("click", "#login_form", function () {
        // var head = document.getElementsByTagName('head')[0];
        // var script = document.createElement('script');
        // script.type = 'text/javascript';
        // script.onload = function() {
        //     grecaptcha.ready(function() {
        //         widgetId_0 = grecaptcha.render('g-recaptcha-signin', {'sitekey' : key_captcha});
        //     });
        // }
        // script.src = "https://www.google.com/recaptcha/api.js?onload=CaptchaCallback&render=explicit";
        // head.appendChild(script);
        $('.alert-error').html('')
        $(".social_login").hide();
        $(".user_login").show();
        return false;
    });

    $(document).on("click", "#register_form", function () {
        // var head = document.getElementsByTagName('head')[0];
        // var script = document.createElement('script');
        // script.type = 'text/javascript';
        // script.onload = function() {
        //     grecaptcha.ready(function() {
        //         widgetId_1 = grecaptcha.render('g-recaptcha-signup', {'sitekey' : key_captcha});
        //     });
        // }
        // script.src = "https://www.google.com/recaptcha/api.js?onload=CaptchaCallback&render=explicit";
        // head.appendChild(script);

        $('.alert-error').html('')
        $(".social_login").hide();
        $(".user_register").show();
        $(".header_title").text('Sign Up');
        return false;
    });

    $(document).on("click", "#forgot_password", function () {
        // var head = document.getElementsByTagName('head')[0];
        // var script = document.createElement('script');
        // script.type = 'text/javascript';
        // script.onload = function() {
        //     grecaptcha.ready(function() {
        //         widgetId_2 = grecaptcha.render('g-recaptcha-forgot-password', {'sitekey' : key_captcha});
        //     });
        // }
        // script.src = "https://www.google.com/recaptcha/api.js?onload=CaptchaCallback&render=explicit";
        // head.appendChild(script);

        $('.alert-error').html('')
        $(".social_login").hide();
        $(".user_register").hide();
        $(".user_login").hide();
        $(".user_forgot_password").show();
        $(".header_title").text('Forgot Password');
        return false;
    });

    $(document).on("click", ".back_btn", function () {
        $('.alert-error').html('')
        $(".user_login").hide();
        $(".user_register").hide();
        $(".user_forgot_password").hide();
        $(".social_login").show();
        $(".header_title").text('Login');
        return false;
    });

    $(document).on("click", ".back_btn_from_forgot_password", function () {
        $('.alert-error').html('')
        $(".user_register").hide();
        $(".user_forgot_password").hide();
        $(".social_login").hide();
        $(".user_login").show();
        $(".header_title").text('Login');
        return false;
    });

    f_reload = false;
    loginAjax = function () {
        $.ajax({
            type: 'POST',
            url: '/loginAjax',
            data: {
                "email": $('.user_login input[type=email]').val().trim(),
                "password": $('.user_login input[type=password]').val().trim(),
                "remember": $('#remember').prop('checked'),
                // "captcha" : grecaptcha.getResponse(widgetId_0),
                "_token": $('meta[name="csrf-token"]').attr('content')
            },
            dataType: 'json',
            beforeSend: function () {
                $('.alert-error').html('');
                $(".ajax_waiting").addClass("loading");
            },
            complete: function () {
                $(".ajax_waiting").removeClass("loading");
            },
            success: function (response) {
                if (response.status == 200) {
                    location.reload();
                } else {
                    alert(response.message || 'An error occurred while logging in. Please try again later.');
                }
            },
            error: function (data) {
                // grecaptcha.reset(widgetId_0);
                $.each(data.responseJSON.errors, function (index, value) {
                    $('.user_login .alert-' + index).html(value).addClass('alert-error');
                });
            }
        });
    }
    registerAjax = function () {
        $.ajax({
            type: 'POST',
            url: '/registerAjax',
            data: {
                "email": $('.user_register input[type=email]').val().trim(),
                "name": $('.user_register input[type=text]').val().trim(),
                "password": $('.user_register input[type=password]').val().trim(),
                "confirm-password": $('.user_register input[name=confirm-password]').val().trim(),
                // "captcha" : grecaptcha.getResponse(widgetId_1),
                "_token": $('meta[name="csrf-token"]').attr('content')
            },
            dataType: 'json',
            beforeSend: function () {
                $('.alert-error').html('');
                $(".ajax_waiting").addClass("loading");
            },
            complete: function () {
                $(".ajax_waiting").removeClass("loading");
            },
            success: function (response) {
                if (response.status == 200) {
                    $(".user_register").hide();
                    showToast('Success! Your account has been registered.', type = "success", reload = true);
                } else {
                    showToast('An error occurred while registering your account. Please try again later.', type = "error", reload = false);
                }
            },
            error: function (data) {
                // grecaptcha.reset(widgetId_1);
                $.each(data.responseJSON.errors, function (index, value) {
                    $('.user_register .alert-' + index).html(value).addClass('alert-error');
                });
            }
        });
    }
    codePasswordResetAjax = function () {
        var email = $('.user_forgot_password input[type=email]').val().trim();
        $.ajax({
            type: 'POST',
            url: '/codePasswordResetAjax',
            data: {
                "email": email,
                // "captcha" : grecaptcha.getResponse(widgetId_2),
                "_token": $('meta[name="csrf-token"]').attr('content')
            },
            beforeSend: function () {
                $('.alert-error').html('');
                $(".ajax_waiting").addClass("loading");
            },
            complete: function () {
                $(".ajax_waiting").removeClass("loading");
            },
            success: function (response) {
                if (response.status == 200) {
                    $(".user_forgot_password").hide();
                    $(".form_alert").show();
                    $(".form_alert .alert").html('<p class="pb-2">A link has been sent to <b>' + email + '</b>. Click the link in the email to reset your password.</p><p>If you don’t see the email, check other places it might be, like your junk, spam, social, or other folders.</p>');
                    $(".header_title").html('&nbsp');
                } else {
                    alert('An error occurred while sending the password reset code. Please try again later.');
                }
            },
            error: function (data) {
                // grecaptcha.reset(widgetId_2);
                $.each(data.responseJSON.errors, function (index, value) {
                    $('.user_forgot_password .alert-' + index).html(value).addClass('alert-error');
                });
            }
        });
    }
})(jQuery);
